Here's the Python function implementing this logic:

```python
def paths_with_obstacles(grid: list[list[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])

    # Initialize the dp table with zeros
    dp = [[0] * cols for _ in range(rows)]

    # Check if the starting cell is blocked
    if grid[0][0] == 1:
        return 0

    # Initialize the first row
    dp[0][0] = 1

    # Fill the first row
    for j in range(1, cols):
        if grid[0][j] == 1:
            dp[0][j] = 0
        else:
            dp[0][j] = dp[0][j - 1]

    # Fill the first column
    for i in range(1, rows):
        if grid[i][0] == 1:
            dp[i][0] = 0
        else:
            dp[i][0] = dp[i - 1][0]

    # Fill the rest of the dp table
    for i in range(1, rows):
        for j in range(1, cols):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]

    # The bottom-right cell contains the number of distinct paths
    return dp[rows - 1][cols - 1]

# Example usage:
grid = [
    [0, 0, 0],
    [0, 1, 0],
    [0, 0, 0]
]
