```python
def evaluate(expr: str) -> int:
    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left // right)

    def precedence(op):
        if op in ('+', '-'):
            return 1
        elif op in ('*', '/'):
            return 2
        return 0

    def apply_operator_stack(operators, values, token):
        while (operators and operators[-1] != '(' and
               precedence(operators[-1]) >= precedence(token)):
            apply_operator(operators, values)
        operators.append(token)

    def apply_operator_stack_end(operators, values):
        while operators:
            apply_operator(operators, values)

    def tokenize(expr):
        tokens = []
        i = 0
        while i < len(expr):
            if expr[i].isdigit():
                j = i
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                tokens.append(int(expr[i:j]))
                i = j
            elif expr[i] in '+-*/()':
                tokens.append(expr[i])
                i += 1
            elif expr[i] == ' ':
                i += 1
        return tokens

    tokens = tokenize(expr)
    operators = []
    values = []

    for token in tokens:
        if token.isdigit():
            values.append(token)
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                apply_operator(operators, values)
            operators.pop()  # Remove '('
        else:
            apply_operator_stack(operators, values, token)

    apply_operator_stack_end(operators, values)

    return values[0]

