To solve the n-queens problem, we can use backtracking, which is a method for finding all solutions to a problem by incrementally building a solution and abandoning it as soon as it is determined that the solution cannot be completed. Here's how we can implement this in Python:

```python
def n_queens(n: int) -> int:
    def is_safe(board, row, col):
        # Check this row on left side
        for i in range(col):
            if board[row][i] == 1:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        # Check lower diagonal on left side
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        return True

    def solve_n_queens_util(board, col):
        if col == n:
            return 1

        count = 0
        for i in range(n):
            if is_safe(board, i, col):
                board[i][col] = 1
                count += solve_n_queens_util(board, col + 1)
                board[i][col] = 0  # backtrack

        return count

    board = [[0] * n for _ in range(n)]
    return solve_n_queens_util(board, 0)

