    def is_safe(board, row, col):
        # Check if there is any queen in the same row
        for i in range(col):
            if board[row][i] == 1:
                return False

        # Check upper diagonal
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
