        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a // b

    def parse_expr(expr: str) -> int:
        stack = []
        ops = []
        num = ''

        for char in expr:
            if char.isdigit():
                num += char
            elif char in '+-*/':
                if num:
                    stack.append(int(num))
                    num = ''
                ops.append(char)
            elif char == '(':
                stack.append('(')
            elif char == ')':
                while stack and stack[-1] != '(':
                    b = stack.pop()
                    a = stack.pop()
                    op = ops.pop()
                    stack.append(apply_operator(a, b, op))
                stack.pop()  # Remove the '('

        if num:
            stack.append(int(num))

        while stack and ops:
            b = stack.pop()
            a = stack.pop()
            op = ops.pop()
            stack.append(apply_operator(a, b, op))

        return stack[0]

    return parse_expr(expr.replace(' ', ''))
