def matmul(a: list[list[float]], b: list[list[float]]) -> list[list[float]]:
    # Check if the number of columns in the first matrix matches the number of rows in the second matrix
    if len(a[0]) != len(b):
        raise ValueError("Number of columns in the first matrix must match the number of rows in the second matrix")

    # Initialize the result matrix with zeros
    result = [[0 for _ in range(len(b[0]))] for _ in range(len(a))]

    # Compute the matrix product
    for i in range(len(a)):
        for j in range(len(b[0])):
            for k in range(len(b)):
                result[i][j] += a[i][k] * b[k][j]

    return result
